#!/usr/bin/env python3
"""The glyphs of KiCad's stroke font, newstroke, as Sources/KiCadRouter/StrokeFontData.swift has them: KiCad's
common/newstroke_font.cpp's table (newstroke_font[], a string for each character from U+0020 on, in the Hershey
font's coding), its strings one a line in a Swift string literal, read by StrokeFont as KiCad's
STROKE_FONT::loadNewStrokeFont reads the table.

    newstroke.py KICAD/common/newstroke_font.cpp OUT.swift
"""

import re
import sys

HEADER = """\
// Generated by tools/kicad-reference/newstroke.py from KiCad 10.0.7's common/newstroke_font.cpp: the glyphs of
// newstroke, KiCad's stroke font, one a line from U+0020 on, in the coding of that file's newstroke_font[].
// Copyright (C) 2010 vladimir uryvaev <vovanius@bk.ru>; Copyright The KiCad Developers, see KiCad's AUTHORS.txt.
// GNU General Public License version 2 or later. Its CJK ideographs: code copyright (c) 2018 Lingdong Huang (MIT
// license), from Source Han Sans, Copyright 2014-2019 Adobe (http://www.adobe.com/), with Reserved Font Name
// 'Source', under the SIL Open Font License, Version 1.1. See KICAD-NOTICE.md for these licenses.

extension StrokeFont {
    /// newstroke_font[]: each glyph's string, one a line
    static let newstrokeTable = {delim}\"\"\"
"""


def main():
    src = open(sys.argv[1], encoding="utf-8").read()
    start = src.index("newstroke_font[] =")
    body = src[start:src.index("};", start)]
    glyphs = []
    for line in body.split("\n"):
        if not line.strip().startswith('"'):
            continue
        literal = re.match(r'\s*"((?:[^"\\]|\\.)*)"', line).group(1)
        glyphs.append(re.sub(r"\\(.)", r"\1", literal))
    # a raw string's delimiter that no glyph's backslash runs into
    delim = "#"
    while any("\\" + delim in g or '"""' + delim in g for g in glyphs):
        delim += "#"
    with open(sys.argv[2], "w") as out:
        out.write(HEADER.replace("{delim}", delim))
        for g in glyphs:
            assert "\n" not in g and g == g.strip()
            out.write(g + "\n")
        out.write('"""' + delim + "\n}\n")


if __name__ == "__main__":
    main()
